package cn.hutool.core.io;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Regression test for FileMagicNumber.AAC.match() ArrayIndexOutOfBoundsException
 * when given a byte array of length 1.
 * <p>
 * The guard checks {@code bytes.length < 1} but then accesses {@code bytes[1]},
 * so a single-byte array triggers {@link ArrayIndexOutOfBoundsException}.
 * Correct behavior: return {@code false} for any array shorter than 2 bytes.
 */
class FileMagicNumberAacMatchTest {

	@Test
	void matchWithSingleByteShouldReturnFalseNotThrow() {
		// AAC magic number requires at least 2 bytes (bytes[0] and bytes[1]).
		// A single byte should safely return false.
		assertFalse(FileMagicNumber.AAC.match(new byte[]{(byte) 0xFF}));
	}

	@Test
	void matchWithEmptyArrayShouldReturnFalse() {
		assertFalse(FileMagicNumber.AAC.match(new byte[0]));
	}

	@Test
	void matchWithTwoBytesMatchingAacShouldReturnTrue() {
		// AAC signature: 0xFF 0xF1 or 0xFF 0xF9
		assertFalse(FileMagicNumber.AAC.match(new byte[]{(byte) 0xFF, (byte) 0xF0}));
		assertTrue(FileMagicNumber.AAC.match(new byte[]{(byte) 0xFF, (byte) 0xF1}));
		assertTrue(FileMagicNumber.AAC.match(new byte[]{(byte) 0xFF, (byte) 0xF9}));
	}
}

