		assertEquals(content, StrUtil.utf8Str(decrypt));

		String encryptHex = des.encryptHex(content);
		String decryptStr = des.decryptStr(encryptHex);

		assertEquals(content, decryptStr);
	}

	@Test
	public void vigenereTest() {
		String content = "Wherethereisawillthereisaway";
		String key = "CompleteVictory";

		String encrypt = Vigenere.encrypt(content, key);
		assertEquals("zXScRZ]KIOMhQjc0\\bYRXZOJK[Vi", encrypt);
		String decrypt = Vigenere.decrypt(encrypt, key);
		assertEquals(content, decrypt);
	}

	@Test
	public void vigenereEmptyKeyTest() {
		String content = "Hello";
		String emptyKey = "";

		// encrypt with empty key should throw IllegalArgumentException, not ArithmeticException
		assertThrows(IllegalArgumentException.class, () -> Vigenere.encrypt(content, emptyKey));
		// decrypt with empty key should also throw IllegalArgumentException
		assertThrows(IllegalArgumentException.class, () -> Vigenere.decrypt(content, emptyKey));
	}
}

