package cn.hutool.core.io;

import static org.junit.jupiter.api.Assertions.assertFalse;
import org.junit.jupiter.api.Test;

/**
 * Test for FileMagicNumber.match() safety with short byte arrays.
 */
public class FileMagicNumberTest {

	@Test
	public void m4aMatchShortArrayNoException() {
		// When bytes.length < 4, the second OR branch in M4A.match()
		// accesses bytes[0], bytes[1], bytes[2], bytes[3] without a length guard.
		// This should return false, not throw ArrayIndexOutOfBoundsException.
		assertFalse(FileMagicNumber.M4A.match(new byte[0]));
		assertFalse(FileMagicNumber.M4A.match(new byte[1]));
		assertFalse(FileMagicNumber.M4A.match(new byte[2]));
		assertFalse(FileMagicNumber.M4A.match(new byte[3]));
	}
}

