	@Test
	public void issueI6MACITest() {
		final File file = FileUtil.file("text.txt");
		final String type = FileTypeUtil.getType(file);
		assertEquals("txt", type);
	}

	@Test
	public void amrMatchWithExactly11BytesShouldNotThrow() {
		// AMR.match() guard checks bytes.length < 11, but flag2 accesses bytes[11].
		// When bytes.length == 11, the guard passes (11 is NOT < 11) but bytes[11]
		// is out of bounds, causing ArrayIndexOutOfBoundsException.
		// Craft bytes[0..10] to match flag2 prefix so short-circuit doesn't stop
		// before the bytes[11] access. The correct behaviour is to return false
		// (no match) without throwing.
		byte[] bytes11 = new byte[11];
		bytes11[0] = (byte) 0x23; // '#'
		bytes11[1] = (byte) 0x21; // '!'
		bytes11[2] = (byte) 0x41; // 'A'
		bytes11[3] = (byte) 0x4D; // 'M'
		bytes11[4] = (byte) 0x52; // 'R'
		bytes11[5] = (byte) 0x5F; // '_'
		bytes11[6] = (byte) 0x4D; // 'M'
		bytes11[7] = (byte) 0x43; // 'C'
		bytes11[8] = (byte) 0x31; // '1'
		bytes11[9] = (byte) 0x2e; // '.'
		bytes11[10] = (byte) 0x30; // '0'
		// Now flag2's short-circuit && will reach bytes[11] -> ArrayIndexOutOfBounds
		boolean result = FileMagicNumber.AMR.match(bytes11);
		assertFalse(result, "AMR should not match this 11-byte array (insufficient for multi-channel header)");
	}

	@Test
	@Disabled
	public void issue3024Test() {
		String x = FileTypeUtil.getType(FileUtil.getInputStream("d:/test/TEST_WPS_DOC.doc"),true);
		System.out.println(x);
	}
}

