package cn.hutool.db.ds.pooled;

import java.sql.SQLException;
import java.util.concurrent.BrokenBarrierException;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.CyclicBarrier;
import java.util.concurrent.atomic.AtomicInteger;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Thread-safety tests for PooledDataSource.
 * Verifies that activeCount is never allowed to exceed maxActive
 * and that no negative activeCount occurs under concurrency.
 */
public class PooledDataSourceConcurrencyTest {

	private PooledDataSource dataSource;

	@BeforeEach
	public void setUp() {
		DbConfig config = new DbConfig();
		config.setUrl("jdbc:h2:mem:testdb;DB_CLOSE_DELAY=-1;DATABASE_TO_UPPER=FALSE");
		config.setDriver("org.h2.Driver");
		config.setUser("sa");
		config.setPass("");
		config.setInitialSize(0);
		config.setMaxActive(5);
		config.setMaxWait(0L);
		dataSource = new PooledDataSource(config);
	}

	@AfterEach
	public void tearDown() {
		if (dataSource != null) {
			dataSource.close();
		}
	}

	/**
	 * Test that concurrent calls to getConnection(long) respect the maxActive limit.
	 * When the pool is at max capacity, further getConnection() calls should throw
	 * SQLException, not silently allow more than maxActive connections.
	 */
	@Test
	public void testConcurrentGetConnectionRespectsMaxActive() throws Exception {
		int maxActive = 5;
		int threadCount = 50;

		CyclicBarrier barrier = new CyclicBarrier(threadCount);
		AtomicInteger successCount = new AtomicInteger(0);
		AtomicInteger exceptionCount = new AtomicInteger(0);
		CountDownLatch latch = new CountDownLatch(threadCount);

		Thread[] threads = new Thread[threadCount];

		for (int i = 0; i < threadCount; i++) {
			threads[i] = new Thread(() -> {
				try {
					barrier.await(); // all threads start at the same moment
					PooledConnection conn = dataSource.getConnection(0L);
					successCount.incrementAndGet();
					// quickly release the connection
					conn.close();
				} catch (SQLException e) {
					// Expected when pool is exhausted
					exceptionCount.incrementAndGet();
				} catch (InterruptedException | BrokenBarrierException e) {
					// ignore for this test
				} finally {
					latch.countDown();
				}
			});
			threads[i].start();
		}

		latch.await();

		int success = successCount.get();
		int exceptions = exceptionCount.get();

		System.out.println("Success count: " + success + ", Exception count: " + exceptions);

		// The key assertion: we should never get more than maxActive connections at once.
		// If the race exists, success count can exceed maxActive because multiple threads
		// pass the check at the same time.
		assertTrue(success <= maxActive, 
			"Expected at most " + maxActive + " successful connections, but got " + success 
			+ ". activeCount race condition allows exceeding maxActive.");
	}
}

