package cn.hutool.db.sql;

import static org.junit.jupiter.api.Assertions.*;

import java.lang.reflect.Method;

import org.junit.jupiter.api.Test;

/**
 * Test for Condition.unwrapQuote bug: StringIndexOutOfBoundsException
 * when given a whitespace-only string.
 */
public class ConditionUnwrapQuoteTest {

	@Test
	public void testUnwrapQuoteWithWhitespaceOnly() throws Exception {
		// Access the private static unwrapQuote method via reflection
		Method unwrapQuote = Condition.class.getDeclaredMethod("unwrapQuote", String.class);
		unwrapQuote.setAccessible(true);

		// A whitespace-only string should NOT throw StringIndexOutOfBoundsException
		// After trim() it becomes empty, but charAt(0) is still called on it
		assertDoesNotThrow(() -> unwrapQuote.invoke(null, "   "));
	}

	@Test
	public void testUnwrapQuoteWithEmptyString() throws Exception {
		Method unwrapQuote = Condition.class.getDeclaredMethod("unwrapQuote", String.class);
		unwrapQuote.setAccessible(true);

		// An empty string should NOT throw StringIndexOutOfBoundsException
		assertDoesNotThrow(() -> unwrapQuote.invoke(null, ""));
	}
}

